/**
 * Datas — porte de `util/datas.js` do legado.
 *
 * Datas de calendário são sempre do fuso **local**, nunca `toISOString()`: em
 * UTC−3, qualquer horário depois das 21h cairia no dia seguinte, e o registro
 * seria criado, filtrado ou exibido no dia errado.
 */

/** `YYYY-MM-DD` local de um `Date`, de um epoch em ms, ou de hoje. */
export function dataLocalISO(data: Date | number = new Date()): string {
  const d = data instanceof Date ? data : new Date(data);
  const mes = String(d.getMonth() + 1).padStart(2, '0');
  const dia = String(d.getDate()).padStart(2, '0');
  return `${d.getFullYear()}-${mes}-${dia}`;
}

/** `YYYY-MM` local — o filtro de mês. */
export function mesLocalISO(data: Date | number = new Date()): string {
  return dataLocalISO(data).slice(0, 7);
}

/** `YYYY-MM-DD` local de hoje mais `dias`. */
export function hojeMaisDiasISO(dias: number): string {
  return dataLocalISO(new Date(Date.now() + dias * 86_400_000));
}

/** Epoch (ms) do início do dia local descrito por `YYYY-MM-DD`. */
export function epochDeDataISO(ymd: string): number {
  const [ano, mes, dia] = ymd.split('-').map(Number);
  return new Date(ano ?? 1970, (mes ?? 1) - 1, dia ?? 1, 0, 0, 0, 0).getTime();
}

/** `dd/mm/aaaa` de um epoch; `—` quando não há data. */
export function dataBR(ms: number | undefined): string {
  return ms === undefined || ms === 0 ? '—' : new Date(ms).toLocaleDateString('pt-BR');
}

/** Número sem zeros à direita, com vírgula decimal. */
export function numero(valor: number | string | undefined): string {
  const n = Number(valor) || 0;
  return Number.isInteger(n)
    ? String(n)
    : n
        .toFixed(2)
        .replace(/\.?0+$/, '')
        .replace('.', ',');
}

/** `R$ 1.234,56`. */
export function moeda(valor: number | string | undefined): string {
  const n = Number(valor) || 0;
  return `R$ ${n.toLocaleString('pt-BR', { minimumFractionDigits: 2, maximumFractionDigits: 2 })}`;
}
